// === Tab: mySketch ===
//For the #wccChallenge on the theme of 'growing'.
//Code by Aaron Reuland.
//I started this project late last summer, but abandoned it. Been walking past the same meadows
//that inspired me then and even though they don't quite look like this yet, I've been enjoying
//the grass moving in sweeping waves to the breeze and looking forward to the sweep of colors
//to come.

joePyeColors = ['#200607', '#651D3DA3', '#CFB8CFC1', '#639b0d']
jewelWeedColors = ['#eec023', '#f47b36', '#74af5a']
bullThistleColors = ['#410d1e', '#d077c5', '#d597cc', '#919572']
grassColors = ['#888539', '#897636', '#9c733f', '#be9563', '#d4ab82', '#f7e0b8']

let farthest
let nearest
let simplex

function setup() {
	createCanvas(windowWidth, windowHeight);
	simplex = new openSimplexNoise(Date.now())
	pixelDensity(1)
	background("#8ddcff")
	loadPixels()
	for (let x = 0; x < width; x++) {
		for (let y = 0; y < height * 0.33; y += floor(random(0, 3))) {
			var index = (x + y * width) * 4;
			let cvalue = noise(x / 300, y / 55)
			if (cvalue < 0.33) {
				let setC = map(cvalue, 0.33, 0, 220, 255)
				pixels[index + 0] = setC;
				pixels[index + 1] = setC;
				pixels[index + 2] = setC;
				pixels[index + 3] = 200
			}
		}
	}
	updatePixels()


	farthest = height * 0.33
	nearest = height + height * 0.1
}

function draw() {
	let amountPerY = width / 300
	if (frameCount < 50) {
		for (let y = farthest; y < nearest; y++) {
			for (let i = 0; i < amountPerY; i++) {
				let x = random(-width * 0.05, width + width * 0.05)
				grass(x, y)
			}
		}


	}
}

function grass(x, y) {
	noFill()
	let scaler = map(y, farthest, nearest, 0.05, 1.5)
	stroke(colorMixer(x, y, grassColors))
	strokeWeight(1 * scaler)
	push()
	translate(x, y)
	let h = (height * 0.2) * scaler
	let cpx1 = simplex.noise3D(x / 100, 1, frameCount / 50) * h
	let cpy1 = noise(y / 100, 1, frameCount / 50) * h
	let cpx2 = simplex.noise3D(x / 100, 2, frameCount / 50) * h
	let cpy2 = -h + simplex.noise3D(y / 100, 2, frameCount / 100) * h / 2
	let apx = simplex.noise3D(x / 100, 3, frameCount / 50) * h
	let apy = -h + simplex.noise4D(y / 100, x, 3, frameCount / 100) * h

	bezier(0, 0, cpx1, cpy1, cpx2, cpy2, apx, apy)

	let flowerChooser = floor(random(700))
	if (flowerChooser <= 1 && y < height * 0.85) {
		push()
		stroke('#200607')
		strokeWeight(2)
		bezier(0, 0, 0, 0, cpx2, cpy2, apx, apy)
		joePyeWeed(apx, apy)
		pop()
	}
	if (flowerChooser > 1 && flowerChooser <= 3.5) {
		jewelWeed(apx, apy)
	}

	if (flowerChooser > 3.5 && flowerChooser <= 5 && y > height * 0.85) {
		bullThistle(apx, apy)
	}
		pop()

}

function joePyeWeed(x, y) {
	push()
	noStroke()
	translate(x, y)
	rotate(simplex.noise3D(x, y, frameCount / 100) * QUARTER_PI)
	let cluster = []
	for (let i = 0; i < 100; i++) {
		let px = random(-20, 20)
		let yrange = map(abs(px), 0, 20, 10, 0)
		let py = random(-yrange, yrange) - 5
		cluster.push(createVector(px, py))
	}

	for (let c of cluster) {
		fill(joePyeColors[1])
		ellipse(c.x, c.y + random(3), 4)
	}
	for (let c of cluster) {
		fill(joePyeColors[2])
		ellipse(c.x + random(-1, 1), c.y + random(-1, 1), 3)
	}

	pop()


}

function jewelWeed(x, y) {
	push()
	let inc = TAU / 10
	translate(x, y)
	for (let i = 0; i < 10; i++) {
		let xoff = random(-30, 30)
		let yoff = random(-y * 0.2, -y * 0.75)
		noStroke()
		fill(jewelWeedColors[0])
		beginShape()
		for (let a = 0; a < TAU; a += inc) {
			let r = noise(cos(a), sin(a), xoff + yoff) * 5
			vertex(xoff + cos(a) * r, yoff + sin(a) * r)
		}
		endShape()
		fill(jewelWeedColors[1])
		beginShape()
		for (let a = 0; a < TAU; a += inc) {
			let r = noise(cos(a), sin(a), xoff + yoff) * 2
			vertex(random(-1, 1) + xoff + cos(a) * r, random(-1, 1) + yoff + sin(a) * r)
		}
		endShape()
	}

	pop()
}

function bullThistle(x, y) {

	for (let i = 0; i < 5; i++) {
		push()
		translate(random(-30, 30), random(-30, 10))
		stroke(bullThistleColors[3])
		strokeWeight(2)
		line(x = 4, y + height * 0.1, x - 4 + random(-3, 3), y + height * 0.1 + 50)

		noStroke()
		let inc = TAU / 10
		fill(bullThistleColors[2])
		beginShape()
		for (let a = 0; a < TAU; a += inc) {
			let r = noise(cos(a), sin(a), x, y) * 15
			vertex(random(-1, 1) + x + cos(a) * r, y + height * 0.1 + random(-1, 1) + sin(a) * r)
		}
		endShape()
		fill(bullThistleColors[1])
		beginShape()
		for (let a = 0; a < TAU; a += inc) {
			let r = noise(cos(a), sin(a), x, y) * 12
			vertex(random(-1, 1) + x + cos(a) * r - 2, y + height * 0.1 + random(-1, 1) + sin(a) * r + 5)
		}
		endShape()
		fill(bullThistleColors[0])
		beginShape()
		for (let a = 0; a < TAU; a += inc) {
			let r = noise(cos(a), sin(a), x, y) * 13
			vertex(random(-1, 1) + x + cos(a) * r - 4, y + height * 0.1 + random(-1, 1) + sin(a) * r + 10)
		}
		endShape()
		pop()
	}

}

function colorMixer(x, y, colorArray) {
	let c = map(y, farthest, nearest, 0, 5) + noise(x / 50, y / 50)
	let c1 = floor(c)
	let c2 = floor(c + 1) % colorArray.length
	let color1 = colorArray[c1]
	let color2 = colorArray[c2]
	let mix = fract(c)
	let coloring = color(spectral.mix(color1, color2, mix))
	return coloring
}
